def maxAverageOfPath(cost):
    """Return the maximum average cell cost over all right/down paths
    from the top-left to the bottom-right cell of a square matrix.

    Every path in an N x N grid visits exactly 2*N - 1 cells (N-1 rights,
    N-1 downs, plus the start). Hence maximizing the average is equivalent
    to maximizing the total cost; the answer is the maximum path sum divided
    by (2*N - 1).
    """
    n = len(cost)
    if n == 0:
        return 0
    num_cells = 2 * n - 1
    dp = [float('-inf')] * n
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[j] = cost[0][0]
            elif i == 0:
                dp[j] = dp[j - 1] + cost[i][j]
            elif j == 0:
                dp[j] = dp[j] + cost[i][j]
            else:
                dp[j] = max(dp[j], dp[j - 1]) + cost[i][j]
    return dp[n - 1] / num_cells

